"""Reuse all first-review regression checks, with explicit second-review expectations."""
from pathlib import Path
import hashlib
ROOT=Path(__file__).resolve().parents[1]
source=(ROOT/'tests/review_1st_browser.py').read_text()
assert hashlib.sha256(source.encode()).hexdigest()=='c0c14697ce8359baaf480ad1af404ad1065140bf50dbb1b592660c1a5cc2d4f2', 'Base browser suite changed; review patch'
source=source.replace('review-1st','review-2nd').replace('review1','review2').replace('1차 검토','2차 검토')
lines=source.splitlines(keepends=True)
edits=[(55, 56, "    check('seven primary menus separate LIVE and content',p.locator('.desktop-nav>a').all_text_contents()==['오늘의 이세돌','멤버 소개','소식·일정','음악','LIVE','콘텐츠','활동 기록'])\n"), (97, 100, '    go(p,\'members\');check(\'operating member list restored\',p.locator(\'.catalog-member-card\').count()==6)\n    check(\'first-review member cards discarded\',p.locator(\'.member-card[data-item-key]\').count()==0)\n    for mid in [\'ine\',\'jingburger\',\'lilpa\',\'jururu\',\'gosegu\',\'viichan\']:\n        go(p,\'member/\'+mid)\n        check(\'operating profile \'+mid,p.locator(\'[data-profile-detail="\'+mid+\'"]\').count()==1 and p.locator(\'.catalog-facts\').count()==1)\n        check(\'no discarded tabs \'+mid,p.locator(\'.tabbar\').count()==0 and p.locator(\'[data-interest]\').count()==0)\n        check(\'original channels \'+mid,p.locator(\'.catalog-channel\').count()>0)\n        check(\'original participation music \'+mid,p.locator(\'.catalog-song\').count()>0)\n    go(p,\'content\');check(\'content has only requested tabs\',p.locator(\'.tabbar .tab\').all_text_contents()==[\'최근 영상\',\'다시보기\',\'시리즈·합방\'])\n    check(\'content defaults to recent videos\',p.locator(\'.content-card\').count()>0 and p.locator(\'[data-live-cards]\').count()==0)\n    go(p,\'live\');check(\'operating live heading\',p.locator(\'h1\').inner_text()==\'지금, 우리와 함께 LIVE\')\n    check(\'operating live toolbar restored\',p.locator(\'[data-live-search],[data-live-sort],[data-live-auto],[data-live-action=refresh]\').count()==4)\n    check(\'operating live has no content tabs\',p.locator(\'.tabbar\').count()==0 and p.locator(\'.live-card\').count()==6)\n    go(p,\'live?tab=replay\');check(\'old content link redirects\',p.evaluate(\'location.hash.startsWith("#/content?")\'))\n'), (104, 104, '    check(\'agency label retained\',p.locator(\'.legend\').inner_text().count(\'소속사 공지\')==1)\n    check(\'calendar colors override muted text\',p.locator(\'.day-chip[data-member-tone=lilpa]\').evaluate_all(\'(es)=>es.length>0&&es.every(e=>getComputedStyle(e).color===getComputedStyle(document.querySelector(".legend .tone-lilpa")).color)\'))\n    check(\'agency first on November 3\',p.locator(\'.day[href*="date=2026-11-03"] .day-chip\').first.get_attribute(\'data-agency\')==\'true\')\n    go(p,\'schedule?month=2026-11&view=list&source=agency\')\n    check(\'agency filter preserves official notices\',p.locator(\'.row-card\').count()>0 and p.locator(\'.row-card[data-agency=false]\').count()==0)\n\n'), (115, 115, "    check('operating history text restored',all(x in p.locator('.story-heading').inner_text() for x in ['OUR STORY','SINCE 2021','차곡차곡, 우리의 발자취.','오디션의 첫 시작부터 음악과 무대, 함께 만든 순간까지.']))\n    check('discarded history copy removed',all(x not in p.locator('#main').inner_text() for x in ['OUR TIMELINE','기록과 기록 사이의 이야기','일상 공지는 소식·일정에서']))\n\n"), (117, 118, "    go(p,'content?tab=replay');check('density applies to media lists',p.locator('.grid.compact').count()==1)\n"), (125, 126, "    go(p,'review');check('second-review scope lists seven choices',p.locator('.review2-summary>a').count()==7)\n"), (148, 149, "    routes=[('home','home'),('members','members'),('member','member/lilpa'),('schedule','schedule?month=2026-11&date=2026-11-03'),('music','music?tab=albums'),('content','content'),('live','live'),('replay','content?tab=replay'),('history','history'),('search','search?q=릴파+11월+3일'),('review','review'),('settings','settings')]\n")]
for start,end,replacement in reversed(edits):lines[start:end]=[replacement]
source=''.join(lines)
assert hashlib.sha256(source.encode()).hexdigest()=='8535cd4e9ff831fc783661a99b6042a2b6186b0256bb5fd34353c5f61dae016e', 'Second-review suite mismatch'
# The first-review baseline stays immutable; its settings UI was explicitly
# discarded in the second-review follow-up. Keep every unrelated regression.
a=source.index("    go(p,'settings');p.locator('[data-setting=gallery]')")
b=source.index("    go(p,'review');check('second-review scope",a)
source=source[:a]+"    go(p,'settings');check('removed settings bookmarks return home',p.evaluate('location.hash==\"#/home\"'));check('settings UI removed',p.locator('[data-setting]').count()==0)\n"+source[b:]
source=source.replace("    go(p,'settings');p.locator('[data-setting=spoilers]').uncheck();p.locator('[data-setting=density]').select_option('cards')\n",'')
source=source.replace(",('settings','settings')",'')
exec(compile(source,str(ROOT/'tests/review_2nd_browser.py'),'exec'),{'__name__':'__main__','__file__':str(ROOT/'tests/review_2nd_browser.py')})
